// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza minimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

// ===== 1) Ler os dados que vieram do Merge =====
const itens = $input.all().map(i => i.json);

let clientes = [];
let investimentos = [];

for (const it of itens) {
  if (Array.isArray(it.body?.clientes)) clientes = it.body.clientes;
  else if (Array.isArray(it.clientes)) clientes = it.clientes;

  if (Array.isArray(it.investimentos)) investimentos = it.investimentos;
}

// ===== 2) Funções auxiliares =====
const pick = (lista) => lista[Math.floor(Math.random() * lista.length)];

// "R$ 12.500,00" -> 12500
const paraNumero = (txt) =>
  Number(String(txt).replace(/[^\d,]/g, "").replace(",", ".")) || 0;

// 12500 -> "R$ 12.500,00"
const paraReal = (n) =>
  n.toLocaleString("pt-BR", { style: "currency", currency: "BRL" })
   .replace(/\u00a0/g, " ");

// ===== 3) Gerar a recomendação de cada cliente =====
const resultados = clientes.map((c) => {
  const nome = c.nome;
  const email = c.email;
  const perfil = c.perfil;
  const saldoNum = paraNumero(c.saldo);

  // produtos do mesmo perfil do cliente
  const doPerfil = investimentos.filter((p) => p.perfil === perfil);

  // produtos que o saldo consegue pagar
  const elegiveis = doPerfil.filter((p) => Number(p.minimo) <= saldoNum);

  let escolhido = null;
  let motivo = "";

  if (elegiveis.length > 0) {
    // REGRA: maior mínimo que o saldo alcança
    // (para escolher o de maior rentabilidade, mude a ordenação aqui)
    escolhido = elegiveis.sort((a, b) => b.minimo - a.minimo)[0];
    motivo = "saldo_ok";
  } else if (doPerfil.length > 0) {
    // saldo menor que todos os mínimos: sugere o mais acessível
    escolhido = doPerfil.sort((a, b) => a.minimo - b.minimo)[0];
    motivo = "saldo_insuficiente";
  } else {
    motivo = "sem_produto_para_o_perfil";
  }

  // ===== 4) Mensagens (3 variações) =====
  let mensagens = [];

  if (escolhido && motivo === "saldo_ok") {
    const prod = escolhido.produto;
    const min = paraReal(Number(escolhido.minimo));
    const saldo = paraReal(saldoNum);
    const rent = escolhido.rentabilidade;

    mensagens = [
      `Olá ${nome}! Pelo seu perfil (${perfil}), uma boa opção é **${prod}** (mínimo ${min}). Com seu saldo atual (${saldo}), você já consegue investir. Rentabilidade: ${rent}.`,
      `Oi ${nome}! Recomendação para perfil ${perfil}: **${prod}** (mínimo ${min}). Seu saldo (${saldo}) já atende o mínimo. Rentabilidade: ${rent}.`,
      `${nome}, indo direto ao ponto: para o perfil ${perfil}, **${prod}** (mínimo ${min}). Você tem ${saldo}, então dá pra aplicar. Rentabilidade: ${rent}.`
    ];
  } else if (escolhido && motivo === "saldo_insuficiente") {
    const prod = escolhido.produto;
    const min = paraReal(Number(escolhido.minimo));
    const saldo = paraReal(saldoNum);

    mensagens = [
      `Olá ${nome}! Para o perfil ${perfil}, a opção mais acessível é **${prod}** (mínimo ${min}). Seu saldo atual (${saldo}) ainda não alcança esse valor, mas falta pouco para começar.`,
      `Oi ${nome}! Seu saldo (${saldo}) ainda está abaixo do mínimo de **${prod}** (${min}), a opção inicial do perfil ${perfil}. Vale juntar mais um pouco.`,
      `${nome}, por enquanto o saldo (${saldo}) não cobre o mínimo de ${min} do **${prod}** (perfil ${perfil}). Assim que chegar lá, é a melhor porta de entrada.`
    ];
  } else {
    mensagens = [
      `Olá ${nome}! Não encontramos um produto para o perfil ${perfil} no momento.`
    ];
  }

  return {
    nome,
    email,
    perfil,
    saldo_texto: c.saldo,
    saldo_num: saldoNum,
    recomendacao: escolhido,
    motivo,
    mensagens,
    mensagem_escolhida: pick(mensagens)
  };
});

// ===== 5) Saída =====
return [{
  json: {
    ok: true,
    total_clientes: resultados.length,
    total_investimentos: investimentos.length,
    resultados
  }
}];

// Pega o array "resultados" gerado no Code anterior
const resultados = $json.resultados || [];

function parseBRL(valor) {
  if (!valor) return 0;
  const s = String(valor)
    .replace("R$", "")
    .replace(/\./g, "")
    .replace(",", ".")
    .trim();
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

// retorna UM ITEM por cliente
const out = resultados.map(c => {
  const saldoNum = c.saldo_num ?? parseBRL(c.saldo_texto ?? c.saldo);

  return {
    json: {
      email_to: c.email,
      nome: c.nome,
      perfil: c.perfil,
      saldo_texto: c.saldo_texto,
      saldo_num: saldoNum,
      recomendacao: c.recomendacao,
      motivo: c.motivo,
      mensagem_escolhida: c.mensagem_escolhida
    }
  };
});

return out;

// ===== Code in JavaScript1 =====
// Espera itens vindos do Merge (dados do cliente + resposta da IA, combinados por posição)

const items = $input.all();

const out = items.map((item) => {
  const j = item.json;

  // ===== 1) Pega o texto bruto gerado pela IA =====
  // O Basic LLM Chain devolve em "text"; outros nós de IA podem usar "content" ou "output_text"
  const rawText = j.text ?? j.content ?? j.output_text ?? j.output ?? "";

  // ===== 2) Tenta converter o texto em JSON =====
  let parsed = {};
  let ok = true;

  try {
    const limpo = String(rawText)
      .replace(/```json/gi, "")
      .replace(/```/g, "")
      .trim();

    parsed = JSON.parse(limpo);
  } catch (e) {
    ok = false;
    parsed = {
      subject: "Erro ao gerar e-mail",
      text_body: "Não foi possível interpretar a resposta da IA.",
      html_body: "<p>Não foi possível interpretar a resposta da IA.</p>"
    };
  }

  // ===== 3) Pega os dados do cliente (vindos do lado do Merge que tem email_to, nome, etc.) =====
  const to = j.email_to ?? j.email ?? j.to ?? "";
  const nome = j.nome ?? "";
  const perfil = j.perfil ?? "";

  const subject = parsed.subject ?? "";
  const text_body = parsed.text_body ?? "";
  const html_body = parsed.html_body ?? "";

  // ===== 4) Monta o item final =====
  return {
    json: {
      ok,
      to,
      subject,
      text_body,
      html_body,

      // (opcional) manter alguns campos úteis pra debug/aula
      meta: {
        nome,
        perfil,
        produto: j.recomendacao?.produto,
        minimo: j.recomendacao?.minimo,
        rentabilidade: j.recomendacao?.rentabilidade,
        motivo: j.motivo
      }
    }
  };
});

return out;

