// Pega todos os itens que caíram no ramo "false" (e-mail inválido)
const items = $input.all();

const linhas = items.map((item, i) => {
  const j = item.json;
  const nome = j.meta?.nome ?? "Nome não informado";
  const to = j.to || "(vazio)";
  return `${i + 1}. ${nome} — e-mail: ${to}`;
});

const corpo_texto =
  `Os seguintes clientes tiveram o e-mail de recomendação não enviado por endereço inválido:\n\n` +
  linhas.join("\n") +
  `\n\nTotal: ${items.length} cliente(s). Revise os cadastros na planilha.`;

const corpo_html =
  `<p>Os seguintes clientes tiveram o e-mail de recomendação <strong>não enviado</strong> por endereço inválido:</p>` +
  `<ul>` +
  items.map((item) => {
    const j = item.json;
    const nome = j.meta?.nome ?? "Nome não informado";
    const to = j.to || "(vazio)";
    return `<li>${nome} — e-mail: ${to}</li>`;
  }).join("") +
  `</ul>` +
  `<p>Total: <strong>${items.length}</strong> cliente(s). Revise os cadastros na planilha.</p>`;

return [{
  json: {
    subject: `Alerta: ${items.length} e-mail(s) inválido(s) no envio de recomendações`,
    text_body: corpo_texto,
    html_body: corpo_html
  }
}];
